  package   org . movsim . input ;   import   java . io . File ;  import   java . net . URL ;  import   java . util . Locale ;  import     org . apache . commons . cli . CommandLine ;  import     org . apache . commons . cli . CommandLineParser ;  import     org . apache . commons . cli . GnuParser ;  import     org . apache . commons . cli . HelpFormatter ;  import     org . apache . commons . cli . Option ;  import     org . apache . commons . cli . OptionBuilder ;  import     org . apache . commons . cli . Options ;  import     org . apache . commons . cli . ParseException ;  import    org . apache . log4j . PropertyConfigurator ;  import   org . movsim . MovsimMain ;  import    org . movsim . simulator . MovsimConstants ;  import     org . movsim . utilities . impl . FileUtils ;   public class SimCommandLine  {   private Options  options ;   private ProjectMetaData  projectMetaData ;   public SimCommandLine  (   String  [ ] args )  {   initLocalizationAndLogger  ( ) ;   projectMetaData =  ProjectMetaData . getInstance  ( ) ;   createOptions  ( ) ;   createParserAndParse  ( args ) ;   final String  projectName =  projectMetaData . getProjectName  ( ) ;  if  (   projectMetaData . isWriteInternalXml  ( ) &&  projectName . isEmpty  ( ) )  {    System . err . println  ( "no xml file for simulation configuration found!" ) ;   System . exit  (  - 1 ) ; }  if  (  !  FileUtils . fileExists  ( projectName ) )  {    System . err . println  (   "no file \"" + projectName + "\" for simulation configuration found!" ) ;   System . exit  (  - 1 ) ; } }   private void createOptions  ( )  {   options =  new Options  ( ) ;   options . addOption  ( "h" , "help" , false , "prints this message" ) ;   options . addOption  ( "d" , "validate" , false , "parses xml input file for validation (without simulation)" ) ;   options . addOption  ( "i" , "internal_xml" , false , "Writes internal xml (the simulation configuration) after validation from dtd. No simulation" ) ;   options . addOption  ( "w" , "write dtd" , false , "writes dtd file to file" ) ;   options . addOption  ( "l" , "log" , false , "writes the file \"log4j.properties\" to file to adjust the logging properties on an individual level" ) ;   options . addOption  ( "v" , "version" , false , "prints version number of this movsim release" ) ;   OptionBuilder . withArgName  ( "file" ) ;   OptionBuilder . hasArg  ( ) ;   OptionBuilder . withDescription  ( "argument has to be a xml file specifing the configuration of the simulation" ) ;   final Option  xmlSimFile =  OptionBuilder . create  ( "f" ) ;   options . addOption  ( xmlSimFile ) ; }   private void createParserAndParse  (   String  [ ] args )  {   final CommandLineParser  parser =  new GnuParser  ( ) ;  try  {   final CommandLine  cmdline =  parser . parse  ( options , args ) ;   parse  ( cmdline ) ; }  catch (   final  ParseException exp )  {    System . out . printf  ( "Parsing failed.  Reason: %s %n" ,  exp . getMessage  ( ) ) ;   optHelp  ( ) ; } }   private void parse  (  CommandLine cmdline )  {  if  (  cmdline . hasOption  ( "h" ) )  {   optHelp  ( ) ; }  if  (  cmdline . hasOption  ( "d" ) )  {   optValidation  ( ) ; }  if  (  cmdline . hasOption  ( "i" ) )  {   optInternalXml  ( ) ; }  if  (  cmdline . hasOption  ( "w" ) )  {   optWriteDtd  ( ) ; }  if  (  cmdline . hasOption  ( "l" ) )  {   optWriteLoggingProperties  ( ) ; }  if  (  cmdline . hasOption  ( "v" ) )  {   optPrintVersion  ( ) ; }   optSimulation  ( cmdline ) ; }   private void optPrintVersion  ( )  {    System . out . println  (  "movsim release version: " +  MovsimConstants . RELEASE_VERSION ) ;   System . exit  ( 0 ) ; }   private void optWriteLoggingProperties  ( )  {  String  resource =     File . separator + "sim" +  File . separator + "log4j.properties" ;  String  filename = "log4j.properties" ;   FileUtils . resourceToFile  ( resource , filename ) ;    System . out . println  (  "logger properties file written to " + filename ) ;   System . exit  ( 0 ) ; }   private void optWriteDtd  ( )  {  String  resource =     File . separator + "sim" +  File . separator + "multiModelTrafficSimulatorInput.dtd" ;  String  filename = "multiModelTrafficSimulatorInput.dtd" ;   FileUtils . resourceToFile  ( resource , filename ) ;    System . out . println  (  "dtd file written to " + filename ) ;   System . exit  ( 0 ) ; }   private void optInternalXml  ( )  {   projectMetaData . setWriteInternalXml  ( true ) ; }   private void optValidation  ( )  {   projectMetaData . setOnlyValidation  ( true ) ; }   private void optSimulation  (  CommandLine cmdline )  {   final String  simulationFilename =  cmdline . getOptionValue  ( 'f' ) ;  if  (  simulationFilename == null )  {    System . err . println  ( "No xml configuration file! Please specify via the option -f." ) ;   System . exit  (  - 1 ) ; } else  {   final boolean  isXml =  validateSimulationFileName  ( simulationFilename ) ;  if  ( isXml )  {   projectMetaData . setProjectName  ( simulationFilename ) ; } } }   private void optHelp  ( )  {    System . out . println  ( "option -h. Exit Programm" ) ;   final HelpFormatter  formatter =  new HelpFormatter  ( ) ;   formatter . printHelp  ( "movsim" , options ) ;   System . exit  ( 0 ) ; }   private boolean validateSimulationFileName  (  String filename )  {   final  int  i =  filename . lastIndexOf  ( ".xml" ) ;  if  (  i < 0 )  {    System . out . println  ( "Please provide simulation file with ending \".xml\" as argument with option -f, exit. " ) ;   System . exit  ( 1 ) ; }  return true ; }   private void initLocalizationAndLogger  ( )  {   Locale . setDefault  (  Locale . US ) ;   final File  file =  new File  ( "log4j.properties" ) ;  if  (   file . exists  ( ) &&  file . isFile  ( ) )  {   PropertyConfigurator . configure  ( "log4j.properties" ) ; } else  {   final URL  log4jConfig =   MovsimMain . class . getResource  ( "/sim/log4j.properties" ) ;   PropertyConfigurator . configure  ( log4jConfig ) ; } } }